class Solution {
public:
    vector<string> res;
    void walk(TreeNode* node, string path) {
        if (!node) return;
        path += to_string(node->val);
        if (!node->left && !node->right) {
            res.push_back(path);
            return;
        }
        walk(node->left, path + "->");
        walk(node->right, path + "->");
    }
    vector<string> binaryTreePaths(TreeNode* root) {
        walk(root, "");
        return res;
    }
};
